script:
(function () {
  if (window.__n8nChatWidgetInjected) return;
  window.__n8nChatWidgetInjected = true;

  if (!document.querySelector('link[data-n8n-chat-font="sora"]')) {
    const fontLink = document.createElement("link");
    fontLink.rel = "stylesheet";
    fontLink.href =
      "https://fonts.googleapis.com/css2?family=Sora:wght@400;600;700&display=swap";
    fontLink.setAttribute("data-n8n-chat-font", "sora");
    document.head.appendChild(fontLink);
  }

  const sessionId =
    window.crypto && crypto.randomUUID
      ? crypto.randomUUID()
      : "sess-" + Date.now() + "-" + Math.random().toString(16).slice(2);

  const webhookUrl =
    "https://n8n.srv1769874.hstgr.cloud/webhook-test/chat-radoslaw_wlodarczyk";

  const config = {
    widgetName: "Rada Radosław",
    welcomeMessage: "Już my Cię u..rządzimy!",
    footerOffsetDesktop: 96,
    footerOffsetMobile: 88,
    rightOffsetDesktop: 24,
    rightOffsetMobile: 12,
    maxWidth: 420,
    maxHeight: 620,
    zIndexToggle: 9990,
    zIndexPanel: 9991
  };

  const styles = `
    .n8n-chat-widget {
      --chat--color-primary: #ff6bcb;
      --chat--color-secondary: #7367f0;
      --chat--color-glass: rgba(255,255,255,0.88);
      --chat--color-font: #232946;
      --chat--color-border: rgba(255,255,255,0.45);
      --chat--offset-bottom: ${config.footerOffsetDesktop}px;
      --chat--offset-right: ${config.rightOffsetDesktop}px;
      --chat--toggle-size: 68px;
      --chat--panel-width: min(${config.maxWidth}px, calc(100vw - 24px));
      --chat--panel-height: min(${config.maxHeight}px, calc(100vh - 160px));
      font-family: 'Sora', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    }

    .n8n-chat-widget,
    .n8n-chat-widget * {
      box-sizing: border-box;
    }

    .n8n-chat-widget .chat-toggle {
      position: fixed;
      right: var(--chat--offset-right);
      bottom: var(--chat--offset-bottom);
      width: var(--chat--toggle-size);
      height: var(--chat--toggle-size);
      border-radius: 999px;
      background: linear-gradient(135deg, var(--chat--color-primary) 0%, var(--chat--color-secondary) 100%);
      color: #fff;
      border: none;
      cursor: pointer;
      box-shadow: 0 10px 30px rgba(115, 103, 240, 0.28);
      z-index: ${config.zIndexToggle};
      display: flex;
      align-items: center;
      justify-content: center;
      transition: transform 0.2s ease, box-shadow 0.2s ease;
      outline: none;
    }

    .n8n-chat-widget .chat-toggle:hover {
      transform: translateY(-2px);
      box-shadow: 0 14px 34px rgba(115, 103, 240, 0.32);
    }

    .n8n-chat-widget .chat-toggle:active {
      transform: scale(0.96);
    }

    .n8n-chat-widget .chat-toggle svg {
      width: 32px;
      height: 32px;
      fill: currentColor;
    }

    .n8n-chat-widget .chat-container {
      position: fixed;
      right: var(--chat--offset-right);
      bottom: calc(var(--chat--offset-bottom) + var(--chat--toggle-size) + 16px);
      width: var(--chat--panel-width);
      height: var(--chat--panel-height);
      border-radius: 24px;
      background: var(--chat--color-glass);
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      box-shadow: 0 18px 48px rgba(31, 41, 55, 0.18);
      border: 1px solid var(--chat--color-border);
      overflow: hidden;
      display: none;
      flex-direction: column;
      z-index: ${config.zIndexPanel};
      animation: n8nChatPopIn 0.28s ease;
    }

    .n8n-chat-widget .chat-container.open {
      display: flex;
    }

    @keyframes n8nChatPopIn {
      from {
        transform: translateY(18px) scale(0.98);
        opacity: 0;
      }
      to {
        transform: translateY(0) scale(1);
        opacity: 1;
      }
    }

    .n8n-chat-widget .brand-header {
      padding: 18px 20px 10px;
      display: flex;
      align-items: center;
      gap: 12px;
      position: relative;
      border-bottom: 1px solid rgba(35, 41, 70, 0.08);
    }

    .n8n-chat-widget .mascot {
      width: 44px;
      height: 44px;
      border-radius: 50%;
      background: linear-gradient(135deg, #ffb86b 0%, #ff6bcb 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 26px;
      flex: 0 0 auto;
    }

    .n8n-chat-widget .brand-title {
      font-size: 20px;
      font-weight: 700;
      color: var(--chat--color-font);
      line-height: 1.2;
      padding-right: 40px;
    }

    .n8n-chat-widget .close-button {
      position: absolute;
      top: 50%;
      right: 14px;
      transform: translateY(-50%);
      background: transparent;
      border: none;
      color: var(--chat--color-font);
      cursor: pointer;
      font-size: 26px;
      line-height: 1;
      opacity: 0.65;
    }

    .n8n-chat-widget .close-button:hover {
      opacity: 1;
    }

    .n8n-chat-widget .chat-messages {
      flex: 1;
      overflow-y: auto;
      padding: 20px;
      display: flex;
      flex-direction: column;
      gap: 12px;
      background: rgba(255,255,255,0.35);
    }

    .n8n-chat-widget .chat-message {
      max-width: 80%;
      padding: 14px 18px;
      border-radius: 18px;
      font-size: 15px;
      line-height: 1.55;
      word-break: break-word;
      white-space: pre-wrap;
    }

    .n8n-chat-widget .chat-message.user {
      align-self: flex-end;
      background: linear-gradient(135deg, #7367f0 0%, #ff6bcb 100%);
      color: #fff;
    }

    .n8n-chat-widget .chat-message.bot {
      align-self: flex-start;
      background: rgba(255,255,255,0.92);
      color: var(--chat--color-font);
      border: 1px solid rgba(255, 107, 203, 0.18);
    }

    .n8n-chat-widget .chat-message.system {
      align-self: center;
      max-width: 92%;
      background: rgba(255, 238, 238, 0.96);
      color: #8a1f1f;
      border: 1px solid rgba(255, 107, 107, 0.26);
      font-size: 14px;
    }

    .n8n-chat-widget .chat-input {
      padding: 14px 16px 16px;
      display: flex;
      gap: 10px;
      align-items: flex-end;
      border-top: 1px solid rgba(35, 41, 70, 0.08);
      background: rgba(255,255,255,0.72);
    }

    .n8n-chat-widget .chat-input textarea {
      flex: 1;
      min-height: 48px;
      max-height: 120px;
      padding: 12px 14px;
      border: 1px solid #e3e3e3;
      border-radius: 16px;
      background: rgba(255,255,255,0.95);
      color: var(--chat--color-font);
      resize: none;
      font-family: inherit;
      font-size: 15px;
      line-height: 1.4;
      outline: none;
    }

    .n8n-chat-widget .chat-input textarea:focus {
      border-color: #ff6bcb;
      box-shadow: 0 0 0 3px rgba(255, 107, 203, 0.12);
    }

    .n8n-chat-widget .chat-input button {
      width: 48px;
      height: 48px;
      border-radius: 999px;
      background: linear-gradient(135deg, #ff6bcb 0%, #7367f0 100%);
      color: #fff;
      border: none;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 20px;
      cursor: pointer;
      flex: 0 0 auto;
    }

    .n8n-chat-widget .chat-input button:disabled,
    .n8n-chat-widget .chat-input textarea:disabled {
      opacity: 0.6;
      cursor: not-allowed;
    }

    @media (max-width: 640px) {
      .n8n-chat-widget {
        --chat--offset-bottom: ${config.footerOffsetMobile}px;
        --chat--offset-right: ${config.rightOffsetMobile}px;
        --chat--toggle-size: 58px;
        --chat--panel-width: calc(100vw - 24px);
        --chat--panel-height: min(68vh, 560px);
      }

      .n8n-chat-widget .chat-container {
        left: 12px;
        right: 12px;
        width: auto;
        border-radius: 20px;
        bottom: calc(var(--chat--offset-bottom) + var(--chat--toggle-size) + 12px);
      }

      .n8n-chat-widget .brand-title {
        font-size: 18px;
      }

      .n8n-chat-widget .chat-messages {
        padding: 16px;
      }

      .n8n-chat-widget .chat-input {
        padding: 12px;
      }
    }
  `;

  const styleSheet = document.createElement("style");
  styleSheet.setAttribute("data-n8n-chat-style", "true");
  styleSheet.textContent = styles;
  document.head.appendChild(styleSheet);

  const widgetContainer = document.createElement("div");
  widgetContainer.className = "n8n-chat-widget";
  document.body.appendChild(widgetContainer);

  const toggleButton = document.createElement("button");
  toggleButton.className = "chat-toggle";
  toggleButton.type = "button";
  toggleButton.setAttribute("aria-label", "Otwórz czat");
  toggleButton.innerHTML = `




  `;
  widgetContainer.appendChild(toggleButton);

  const chatContainer = document.createElement("div");
  chatContainer.className = "chat-container";
  widgetContainer.appendChild(chatContainer);

  const brandHeader = document.createElement("div");
  brandHeader.className = "brand-header";
  brandHeader.innerHTML = `

🤖

${config.widgetName}
    ×
  `;
  chatContainer.appendChild(brandHeader);

  const messagesContainer = document.createElement("div");
  messagesContainer.className = "chat-messages";
  chatContainer.appendChild(messagesContainer);

  const chatInput = document.createElement("div");
  chatInput.className = "chat-input";
  chatInput.innerHTML = `

    ➤
  `;
  chatContainer.appendChild(chatInput);

  const textarea = chatInput.querySelector("textarea");
  const sendButton = chatInput.querySelector("button");
  const closeButton = brandHeader.querySelector(".close-button");

  function autoResizeTextarea() {
    textarea.style.height = "auto";
    textarea.style.height = Math.min(textarea.scrollHeight, 120) + "px";
  }

  function addMessage(text, type = "bot") {
    const messageDiv = document.createElement("div");
    messageDiv.className = `chat-message ${type}`;
    messageDiv.textContent =
      typeof text === "string" ? text : JSON.stringify(text, null, 2);
    messagesContainer.appendChild(messageDiv);
    messagesContainer.scrollTop = messagesContainer.scrollHeight;
  }

  function setLoadingState(isLoading) {
    textarea.disabled = isLoading;
    sendButton.disabled = isLoading;
    sendButton.textContent = isLoading ? "…" : "➤";
  }

  function extractBotReply(data) {
    if (!data) return "Brak odpowiedzi z workflow.";
    if (typeof data === "string") return data;
    if (data.message) return data.message;
    if (data.reply) return data.reply;
    if (data.output) return data.output;
    if (data.text) return data.text;
    if (data.response) return data.response;

    if (data.data) {
      return typeof data.data === "string"
        ? data.data
        : JSON.stringify(data.data, null, 2);
    }

    if (Array.isArray(data) && data.length > 0) {
      const first = data[0];
      if (typeof first === "string") return first;
      if (first?.message) return first.message;
      if (first?.reply) return first.reply;
      if (first?.output) return first.output;
      if (first?.text) return first.text;
      if (first?.response) return first.response;
      return JSON.stringify(first, null, 2);
    }

    return JSON.stringify(data, null, 2);
  }

  async function sendMessage() {
    const message = textarea.value.trim();
    if (!message) return;

    addMessage(message, "user");
    textarea.value = "";
    autoResizeTextarea();
    setLoadingState(true);

    try {
      const response = await fetch(webhookUrl, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Accept: "application/json, text/plain, */*"
        },
        body: JSON.stringify({
          message,
          sessionId,
          source: window.location.hostname,
          pageUrl: window.location.href,
          userAgent: navigator.userAgent,
          timestamp: new Date().toISOString()
        })
      });

      const contentType = response.headers.get("content-type") || "";
      let data;

      if (contentType.includes("application/json")) {
        data = await response.json();
      } else {
        data = await response.text();
      }

      if (!response.ok) {
        throw new Error(typeof data === "string" ? data : `HTTP ${response.status}`);
      }

      addMessage(extractBotReply(data), "bot");
    } catch (error) {
      console.error("Błąd połączenia z n8n:", error);
      addMessage(
        "Nie udało się pobrać odpowiedzi z n8n. Sprawdź webhook, metodę HTTP w workflow i odpowiedź z node'a Respond to Webhook.",
        "system"
      );
    } finally {
      setLoadingState(false);
      textarea.focus();
      autoResizeTextarea();
    }
  }

  function openChat() {
    chatContainer.classList.add("open");
    textarea.focus();
  }

  function closeChat() {
    chatContainer.classList.remove("open");
  }

  toggleButton.addEventListener("click", () => {
    if (chatContainer.classList.contains("open")) {
      closeChat();
    } else {
      openChat();
    }
  });

  closeButton.addEventListener("click", closeChat);
  sendButton.addEventListener("click", sendMessage);

  textarea.addEventListener("input", autoResizeTextarea);

  textarea.addEventListener("keydown", (e) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  });

  addMessage(config.welcomeMessage, "bot");
  autoResizeTextarea();
})();
